const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
// 1. Define Punjab and Haryana region (approximate bounding box)
var punjabHaryana = ee.Geometry.Polygon([
  [[73.5, 29.0], [78.5, 29.0], [78.5, 32.0], [73.5, 32.0], [73.5, 29.0]]
]);

// 2. Initialize results dictionary
var yearCounts = {};

// 3. Loop through years 2012-2024
for (var year = 2012; year <= 2024; year++) {
  var startDate = ee.Date.fromYMD(year, 1, 1);
  var endDate = ee.Date.fromYMD(year, 12, 31);

  // Get MODIS Active Fire data
  var fires = ee.ImageCollection('MODIS/006/MCD14DL')
    .filterDate(startDate, endDate)
    .filterBounds(punjabHaryana);

  var count = fires.size().getInfo();

  if (count > 0) {
    // Count fire pixels - use 'confidence' band > 0
    var fireMask = fires.select('confidence').gt(0);
    var totalFires = fireMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: punjabHaryana,
      scale: 1000,
      maxPixels: 1e9
    }).get('confidence').getInfo();

    yearCounts[year] = totalFires || 0;
    print(year + ': ' + count + ' images, Fire count: ' + (totalFires || 0));
  } else {
    yearCounts[year] = 0;
    print(year + ': 0 images, Fire count: 0');
  }
}

// 4. Check for C1 (no data for any year)
var hasData = Object.values(yearCounts).some(count => count > 0);
if (!hasData) {
  print("<answer>C1</answer>");
  return;
}

// 5. Find max year
var maxCount = Math.max(...Object.values(yearCounts));
var maxYear = Object.keys(yearCounts).find(year => yearCounts[year] === maxCount);

print('Maximum fire count: ' + maxCount + ' in year ' + maxYear);
print('2016 fire count: ' + (yearCounts[2016] || 0));

// 6. Determine answer
if (maxYear == '2016') {
  print("<answer>A</answer>");
} else {
  print("<answer>B</answer>");
}
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
